TLDR.
CUDAPluggableAllocator will receive malloc request with size of zero. This will happen when we try to allocate a zero size tensor. Zero tensor is allowed in Pytorch, but what should be the expected behavior of an allocator? Are we supposed to return a nullptr?
How to test?
# pluggable.py
import torch

def get_cuda_malloc_allocator():
    """Get the cuda_malloc_with_pluggable allocator."""
    print("current directory: ", os.getcwd())

    allocator_path = 'allocate.so'
    new_alloc = torch.cuda.memory.CUDAPluggableAllocator(
        allocator_path, 'cuda_malloc', 'cuda_free')
    return new_alloc

allocator = get_cuda_malloc_allocator()
torch.cuda.memory.change_current_allocator(allocator)
a = torch.Tensor().to("cuda")
b = torch.Tensor([1,2, 4]).to("cuda")
print(a.device)
print(a.size())
// simple_allocate.cpp for pluggable allocator
#include <sys/types.h>
#include <cuda_runtime_api.h>
#include <iostream>
#include <cstdint>


extern "C" {

  void* cuda_malloc(ssize_t size, int device, cudaStream_t stream) {
    void *ptr;
    cudaError_t err;
    std::cout<< "CUDA DEBUG" <<"cuda_malloc "<<ptr<< " " <<size<<std::endl;
    err = cudaMalloc(&ptr, size);
    if (err != cudaSuccess) {
        std::cerr << "cudaMalloc failed: " << cudaGetErrorString(err) << " " << size << std::endl;
        return nullptr;
    }
    // cudaMallocManaged(&ptr, size);
    return ptr;
  }

  void cuda_free(void* ptr, ssize_t size, int device, cudaStream_t stream) {
    std::cout<< "CUDA DEBUG" <<" cudaFree "<<ptr<< " " <<size<<std::endl;
    cudaFree(ptr);
  }
}

Command to reproduce
export CUDA_HOME=${CONDA_PREFIX}/targets/x86_64-linux
export LD_LIBRARY_PATH=$PWD:$LD_LIBRARY_PATH
g++ simple_allocate.cpp -o allocate.so --shared -fPIC -I$CUDA_HOME/include
python pluggable.py

Other helpful info
cudaMalloc returns a nullptr but cudaSuccess when it receives a allocation of size 0. The native CUDACachingAllocator doesn't have the issue; it creates a block with kMinBlockSize (512 bytes) code pointer.
